import{_ as t,o as r,c as a,a6 as n}from"./chunks/framework.CanHnaWe.js";const h=JSON.parse('{"title":"Séance 4 — Orchestration et pratique professionnelle","description":"","frontmatter":{},"headers":[],"relativePath":"seances/04-orchestration-et-pratique-pro.md","filePath":"seances/04-orchestration-et-pratique-pro.md"}'),i={name:"seances/04-orchestration-et-pratique-pro.md"};function s(o,e,l,u,c,d){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="seance-4-—-orchestration-et-pratique-professionnelle" tabindex="-1">Séance 4 — Orchestration et pratique professionnelle <a class="header-anchor" href="#seance-4-—-orchestration-et-pratique-professionnelle" aria-label="Permalink to &quot;Séance 4 — Orchestration et pratique professionnelle&quot;">​</a></h1><p><strong>Jeudi 10 décembre · 3 heures</strong></p><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><p>À la fin de la séance, vous pouvez :</p><ul><li><strong>étendre un agent</strong> : serveur MCP, commande réutilisable (<em>prompt file</em>), agent personnalisé ;</li><li>confier une tâche à un <strong>sous-agent</strong> ou à un <strong>agent en arrière-plan</strong>, et faire travailler des agents <strong>en parallèle</strong> ;</li><li>savoir quand <strong>ne pas</strong> orchestrer : coût, complexité, difficulté à vérifier ;</li><li>reconnaître les <strong>risques</strong> d&#39;une pratique avec l&#39;IA : injection de prompt, secrets, paquets inventés, confidentialité, licences, dette technique, perte de compétences.</li></ul><h2 id="avant-la-seance" tabindex="-1">Avant la séance <a class="header-anchor" href="#avant-la-seance" aria-label="Permalink to &quot;Avant la séance&quot;">​</a></h2><p>Terminez la fonctionnalité commencée à la séance 3 et poussez-la dans votre dépôt.</p><h2 id="deroulement" tabindex="-1">Déroulement <a class="header-anchor" href="#deroulement" aria-label="Permalink to &quot;Déroulement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Durée</th><th>Activité</th></tr></thead><tbody><tr><td>30 min</td><td>Étendre l&#39;agent : brancher un serveur MCP, créer une commande et un agent personnalisés.</td></tr><tr><td>30 min</td><td>Sous-agents, travail en parallèle, agent en arrière-plan sur une issue GitHub (démonstration).</td></tr><tr><td>10 min</td><td>Pause</td></tr><tr><td>55 min</td><td><strong>Activité</strong></td></tr><tr><td>25 min</td><td>Pratique professionnelle : sécurité, confidentialité et Loi 25, licences, dette, compétences.</td></tr><tr><td>30 min</td><td><strong>Retour au diagnostic</strong> de la séance 1, puis bilan du cours.</td></tr></tbody></table><h2 id="activite" tabindex="-1">Activité <a class="header-anchor" href="#activite" aria-label="Permalink to &quot;Activité&quot;">​</a></h2><ol><li>Créez une commande réutilisable <code>/nouvelle-vue</code> qui produit une vue, son ViewModel et ses tests selon les conventions du projet.</li><li>Créez un <strong>agent réviseur</strong> qui relit une pull request et signale tout écart aux règles MVVM du cours.</li><li>Confiez à un agent une issue de <strong>dette technique</strong> de Jumelo, puis relisez sa pull request comme un réviseur.</li><li>Lancez <strong>deux tâches en parallèle</strong>, chacune dans sa propre branche, et intégrez-les.</li></ol><h2 id="retour-au-diagnostic" tabindex="-1">Retour au diagnostic <a class="header-anchor" href="#retour-au-diagnostic" aria-label="Permalink to &quot;Retour au diagnostic&quot;">​</a></h2><p>Reprenez le problème de la séance 1 avec tout ce que vous avez appris. Comparez vos requêtes, le temps passé et la qualité du résultat avec ce que vous aviez fait au premier jour.</p><h2 id="notions-a-retenir" tabindex="-1">Notions à retenir <a class="header-anchor" href="#notions-a-retenir" aria-label="Permalink to &quot;Notions à retenir&quot;">​</a></h2><ul><li>Un agent qui lit une page web, un fichier ou un serveur MCP peut y trouver des instructions malveillantes : le contenu lu n&#39;est jamais un ordre.</li><li>Pas de secret dans le contexte, et pas de code propriétaire dans un outil que votre employeur n&#39;a pas approuvé.</li><li>Vérifiez qu&#39;un paquet proposé par l&#39;IA existe vraiment avant de l&#39;installer.</li><li>Orchestrer plusieurs agents multiplie aussi le code à relire : vous signez tout ce qui est livré.</li></ul>',15)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
